-- 4-bo'lim: Facebook Pixel. Oddiy testlar (4-1 … 4-8) + rasmli testlar (4-1r … 4-8r).
-- Avval images zip'ni GitHub'ga joylang, keyin shu SQL'ni Supabase SQL Editor'da bir marta Run qiling.

-- ===== ODDIY TESTLAR =====
insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'4-1', '4. Facebook Pixel', 4, 1, '1. Facebook Pixel nima', $json$[{"id": "q1", "prompt": "Ustoz Facebook Pixelni nimaga o'xshatdi?", "options": [{"id": "a", "text": "Do'kondagi kassa apparatiga"}, {"id": "b", "text": "Ko'p qavatli uyga o'rnatilgan kameralarga: kim kelganini, qaysi xonadonga kirganini kuzatib, alohida-alohida hisoblab boradi"}, {"id": "c", "text": "Uyning eshik qulfiga"}, {"id": "d", "text": "Pochta qutisiga"}], "correct_option_id": "b", "explanation": "Kameralar uyga kirgan har bir odamni kuzatgani kabi, pixel ham saytga kelgan odamlarni va ular qaysi sahifaga kirib, nima qilganini kuzatadi."}, {"id": "q2", "prompt": "Facebook Pixel aslida nima?", "options": [{"id": "a", "text": "Facebook sahifadagi post turi"}, {"id": "b", "text": "Instagram profilga qo'yiladigan maxsus rasm"}, {"id": "c", "text": "Saytga o'rnatiladigan kod. U saytga kelgan trafikni kuzatib, odamlarni qilgan harakatiga qarab alohida «savatchalarga» ajratadi"}, {"id": "d", "text": "Reklama uchun to'lov kartasi"}], "correct_option_id": "c", "explanation": "Pixel bir qator koddan iborat. Saytga qo'yilgach, kim qaysi sahifaga kirdi, kim qaysi tugmani bosdi, hammasini alohida savatchalarga yig'ib boradi."}, {"id": "q3", "prompt": "Saytda qaysi pixel va qaysi eventlar o'rnatilganini ko'rish uchun Google Chrome'ga qaysi kengaytma (extension) o'rnatiladi?", "options": [{"id": "a", "text": "Meta Pixel Helper"}, {"id": "b", "text": "Google Translate"}, {"id": "c", "text": "AdBlock"}, {"id": "d", "text": "Grammarly"}], "correct_option_id": "a", "explanation": "Meta Pixel Helper saytdagi pixellar sonini, ID raqamini va ishlayotgan eventlarni ko'rsatadi. Keyingi darslarda u doim kerak bo'ladi."}, {"id": "q4", "prompt": "Meta Pixel Helper o'rnatildi, lekin brauzerning yuqori panelida ko'rinmayapti. Nima qilinadi?", "options": [{"id": "a", "text": "Kengaytmalar (Extensions) belgisini bosib, Meta Pixel Helper'ni panelga mahkamlab (pin) qo'yiladi"}, {"id": "b", "text": "Kompyuter qayta yoqiladi"}, {"id": "c", "text": "Hech narsa qilib bo'lmaydi, u faqat telefonda ishlaydi"}, {"id": "d", "text": "Chrome'ni o'chirib, qaytadan o'rnatiladi"}], "correct_option_id": "a", "explanation": "Kengaytmalar ro'yxatida Meta Pixel Helper yonidagi «mahkamlash» belgisini bossangiz, u doim yuqorida ko'rinib turadi."}, {"id": "q5", "prompt": "Pixel o'rnatilgan saytga kirdingiz. Siz hech qanday event sozlamagan bo'lsangiz ham, qaysi event avtomatik ishlaydi?", "options": [{"id": "a", "text": "PageView, ya'ni sahifani ko'rish"}, {"id": "b", "text": "Purchase (Xarid)"}, {"id": "c", "text": "Lead (Lid)"}, {"id": "d", "text": "CompleteRegistration (Ro'yxatdan o'tish)"}], "correct_option_id": "a", "explanation": "PageView pixelning o'z standart eventi. Odam saytning istalgan sahifasini ochganda avtomatik ishlaydi va hamma kirganlarni bitta savatchaga yig'adi."}, {"id": "q6", "prompt": "Ustoz webinarga ro'yxatdan o'tish anketasini to'ldirib, keyingi sahifaga o'tdi. Pixel Helper'da PageView'dan tashqari qaysi event paydo bo'ldi?", "options": [{"id": "a", "text": "«Поиск» (Search)"}, {"id": "b", "text": "«Добавление в корзину» (Add to cart)"}, {"id": "c", "text": "«Завершение регистрации» (Complete registration)"}, {"id": "d", "text": "«Покупка» (Purchase)"}], "correct_option_id": "c", "explanation": "Ustoz shu sahifaga Complete registration eventini o'rnatgan edi. Endi ro'yxatdan o'tgan odamlar alohida savatchaga yig'iladi."}, {"id": "q7", "prompt": "Pixelning IKKINCHI imkoniyati nima?", "options": [{"id": "a", "text": "Saytni avtomatik ravishda chiroyli qiladi"}, {"id": "b", "text": "Reklamani bepul ko'rsatadi"}, {"id": "c", "text": "Reklama orqali kelgan odamlar qancha event bajarganini va bitta natija (masalan, ro'yxatdan o'tish) necha pulga tushganini ko'rsatadi"}, {"id": "d", "text": "Mijozlarga avtomatik SMS yuboradi"}], "correct_option_id": "c", "explanation": "Ads Manager'da har bir reklama bo'yicha natijalar soni va narxi ko'rinadi. Shundan qaysi reklama yaxshi ishlayotganini bilasiz."}, {"id": "q8", "prompt": "Ustoz misolida «Video 5» reklamasi 250 ta ro'yxatdan o'tish olib keldi va unga 25$ sarflandi. Bitta ro'yxatdan o'tish necha pulga tushgan?", "options": [{"id": "a", "text": "25 sent"}, {"id": "b", "text": "2,5 dollar"}, {"id": "c", "text": "10 sent"}, {"id": "d", "text": "1 dollar"}], "correct_option_id": "c", "explanation": "25$ ÷ 250 = 0,10$, ya'ni 10 sent. Shu raqamlar orqali qaysi reklama arzonroq natija berayotganini solishtiramiz."}, {"id": "q9", "prompt": "Nega ustoz lidlarni Instagram/Facebook formasi yoki Google Form orqali emas, sayt orqali yig'ishni maslahat beradi?", "options": [{"id": "a", "text": "Google Form'ni Facebook taqiqlagan"}, {"id": "b", "text": "Sayt orqali reklama bepul bo'ladi"}, {"id": "c", "text": "Instagram formasi faqat telefonda ishlaydi"}, {"id": "d", "text": "U formalarga Facebook Pixel o'rnatib bo'lmaydi. Saytga esa o'rnatib, hamma statistikani ko'rish mumkin"}], "correct_option_id": "d", "explanation": "Pixel bo'lmasa, raqamlarni ko'rmaysiz. Raqamlarni ko'rmasangiz, muammo qayerdaligini bilmaysiz va uni tuzata olmaysiz."}, {"id": "q10", "prompt": "Pixelning UCHINCHI imkoniyati nima?", "options": [{"id": "a", "text": "Facebook sahifaga obunachi qo'shish"}, {"id": "b", "text": "Saytdagi narxlarni avtomatik o'zgartirish"}, {"id": "c", "text": "Raqobatchilarning saytini kuzatish"}, {"id": "d", "text": "Eventlar bo'yicha ajratilgan savatchalardan auditoriya yaratib, masalan saytga kirib anketa to'ldirmaganlarga qayta reklama ko'rsatish"}], "correct_option_id": "d", "explanation": "Saytga bir marta kirgan odamda qiziqish bor. Unga qayta reklama ko'rsatish butunlay notanish odamga ko'rsatishdan ko'ra mijozga aylantirish ehtimoli yuqori."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'4-2', '4. Facebook Pixel', 4, 2, '2. Tilda''ga pixel o''rnatish', $json$[{"id": "q1", "prompt": "Business Manager'da yangi pixel qayerda yaratiladi?", "options": [{"id": "a", "text": "Ads Manager > «Кампании»"}, {"id": "b", "text": "«Настройки компании» (Business settings) > «Источники данных» (Data sources) > «Наборы данных» (Datasets)"}, {"id": "c", "text": "«Настройки компании» > «Пользователи» > «Люди»"}, {"id": "d", "text": "Facebook sahifa > «Настройки»"}], "correct_option_id": "b", "explanation": "Ustoz aytganidek, pixel yaratish imkoniyatlari «Наборы данных» bo'limida joylashgan. U yerdan pixel yaratib, saytlarga o'rnatamiz."}, {"id": "q2", "prompt": "Sizda 4-5 ta sayt bor. Ustoz pixel haqida nimani tavsiya qiladi?", "options": [{"id": "a", "text": "Hamma saytga bitta pixel qo'yish, chunki bu arzonroq"}, {"id": "b", "text": "Faqat eng katta saytga pixel qo'yish"}, {"id": "c", "text": "Pixelni saytga emas, Instagram profilga qo'yish"}, {"id": "d", "text": "Har bir saytga alohida pixel yaratib o'rnatish, chunki har bir saytning ma'lumotlari, auditoriyasi va bazasi aralashib ketmasligi kerak"}], "correct_option_id": "d", "explanation": "Har bir saytning auditoriyasi va ma'lumotlari alohida bo'lishi kerak. Shunda natijalarni ham alohida kuzatib borasiz."}, {"id": "q3", "prompt": "Yangi pixelga nom berayotganda nima yozish tavsiya qilinadi?", "options": [{"id": "a", "text": "Tasodifiy raqamlar"}, {"id": "b", "text": "Ism-familiyangiz"}, {"id": "c", "text": "Telefon raqamingiz"}, {"id": "d", "text": "Pixel qaysi saytga o'rnatilsa, o'sha saytning nomi"}], "correct_option_id": "d", "explanation": "Keyinchalik bir nechta pixelingiz bo'lsa, qaysi pixel qaysi saytga o'rnatilganini nomidan darrov bilib olasiz."}, {"id": "q4", "prompt": "Ustoz test saytiga kirib, Meta Pixel Helper'ni bosganda «No pixel found» yozuvi chiqdi. Bu nimani bildiradi?", "options": [{"id": "a", "text": "Sayt o'chirib yuborilgan"}, {"id": "b", "text": "Pixel o'rnatilgan va to'g'ri ishlayapti"}, {"id": "c", "text": "Bu saytda hali pixel o'rnatilmagan"}, {"id": "d", "text": "Internet ishlamayapti"}], "correct_option_id": "c", "explanation": "«No pixel found» — «pixel topilmadi». Pixel o'rnatilgandan keyin bu yerda pixel ID'si va eventlar ko'rinadi."}, {"id": "q5", "prompt": "Tilda'ga ID orqali pixel o'rnatishda Pixel ID raqami qayerga qo'yiladi?", "options": [{"id": "a", "text": "Sayt nomi o'rniga yoziladi"}, {"id": "b", "text": "Sayt sozlamalari > «Аналитика» (Analytics) > «Facebook Pixel» maydoniga"}, {"id": "c", "text": "Tilda'dagi «Домен» maydoniga"}, {"id": "d", "text": "Sahifaning eng pastki blokiga matn qilib yoziladi"}], "correct_option_id": "b", "explanation": "Events Manager'dan Pixel ID (faqat raqamlar) nusxalanadi, Tilda sozlamalaridagi Analitika bo'limida Facebook Pixel maydoniga qo'yilib, saqlanadi."}, {"id": "q6", "prompt": "Pixel ID qo'yildi va saqlandi, lekin Pixel Helper hali ham pixelni ko'rsatmayapti. Nima qilish kerak?", "options": [{"id": "a", "text": "Barcha sahifalarni qayta nashr qilish (Опубликовать / Publish), chunki saytdagi har qanday o'zgarish nashrdan keyin kuchga kiradi"}, {"id": "b", "text": "Pixelni o'chirib, yangisini yaratish"}, {"id": "c", "text": "24 soat kutish, boshqa hech narsa qilmaslik"}, {"id": "d", "text": "Tilda'dan boshqa platformaga o'tish"}], "correct_option_id": "a", "explanation": "Ustoz: saytga kod yoki o'zgarish kiritsangiz, albatta hamma sahifalarni qaytadan nashr qilishingiz kerak. Shundan keyin pixel ishlaydi."}, {"id": "q7", "prompt": "Pixelni kod orqali o'rnatish uchun kod Events Manager'da qayerdan olinadi?", "options": [{"id": "a", "text": "«Диагностика» bo'limidan"}, {"id": "b", "text": "Ads Manager'dagi reklama matnidan"}, {"id": "c", "text": "«Тестовые события» bo'limidan"}, {"id": "d", "text": "«Настроить пиксель Meta» > «Сбор событий на сайте из браузера» > «Установить код вручную» (Install code manually)"}], "correct_option_id": "d", "explanation": "Bu pixel o'rnatishning ikkinchi usuli. Birinchi usul ID'ni Analitikaga qo'yish, ikkinchisi tayyor kodni nusxalab saytga qo'yish."}, {"id": "q8", "prompt": "Tilda'da pixel kodi qayerga qo'yiladi?", "options": [{"id": "a", "text": "Sayt sarlavhasi (title) maydoniga"}, {"id": "b", "text": "«Аналитика» bo'limidagi Google Analytics maydoniga"}, {"id": "c", "text": "Har bir sahifaning eng pastki blokiga"}, {"id": "d", "text": "Sayt sozlamalari > «Ещё» (More) > «HTML-код для вставки внутрь head» bo'limiga"}], "correct_option_id": "d", "explanation": "Facebook yo'riqnomasi bo'yicha pixel kodi saytning head qismiga qo'yilishi kerak. Saqlagandan keyin sahifalar qayta nashr qilinadi."}, {"id": "q9", "prompt": "Ustoz o'z saytiga nechta pixel o'rnatgan va nima uchun?", "options": [{"id": "a", "text": "1 ta, chunki bittadan ko'p qo'yib bo'lmaydi"}, {"id": "b", "text": "3 ta. Pixel yoki reklama akkaunti, BM bloklanib qolsa, yig'ilgan auditoriya, savatchalar va bazani yo'qotmaslik uchun"}, {"id": "c", "text": "10 ta, chunki pixel qancha ko'p bo'lsa reklama shuncha arzon"}, {"id": "d", "text": "3 ta, chunki har bir pixel faqat bitta sahifani kuzatadi"}], "correct_option_id": "b", "explanation": "Bitta pixel bloklansa ham, qolgan pixellardagi ma'lumotlardan foydalanishda davom etasiz. Ustoz kamida 2 ta pixel qo'yishni maslahat beradi."}, {"id": "q10", "prompt": "Tilda saytiga bir nechta pixel qanday o'rnatiladi?", "options": [{"id": "a", "text": "Har bir pixel uchun alohida sayt ochish orqali"}, {"id": "b", "text": "Faqat birinchi pixelni o'chirib, ikkinchisini qo'yish orqali"}, {"id": "c", "text": "Buning iloji yo'q, bitta saytga bitta pixel qo'yiladi"}, {"id": "d", "text": "Bittasini ID orqali Analitikaga, qolganlarining kodlarini head bo'limiga ketma-ket qo'yish orqali"}], "correct_option_id": "d", "explanation": "Head bo'limiga birinchi pixel kodi, uning ostiga ikkinchisi, keyin uchinchisi qo'yiladi. Shunday qilib bitta saytga bir nechta pixel o'rnatiladi."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'4-3', '4. Facebook Pixel', 4, 3, '3. WordPress''ga pixel o''rnatish', $json$[{"id": "q1", "prompt": "WordPress saytga Facebook Pixel necha xil usulda o'rnatiladi?", "options": [{"id": "a", "text": "WordPress'ga pixel o'rnatib bo'lmaydi"}, {"id": "b", "text": "Faqat ID orqali"}, {"id": "c", "text": "2 xil: Pixel ID orqali va kod orqali"}, {"id": "d", "text": "Faqat 1 xil: kod orqali"}], "correct_option_id": "c", "explanation": "Tilda'dagi kabi WordPress'da ham ikki yo'l bor: plagin orqali ID kiritish yoki kodni sayt header'iga qo'yish."}, {"id": "q2", "prompt": "WordPress'ga pixelni ID orqali o'rnatishda qaysi plagin yordam beradi?", "options": [{"id": "a", "text": "Yoast SEO"}, {"id": "b", "text": "Code Snippets"}, {"id": "c", "text": "WooCommerce"}, {"id": "d", "text": "PixelYourSite"}], "correct_option_id": "d", "explanation": "«Плагины» (Plugins) > yangi plagin qo'shish bo'limida «pixel» deb qidiriladi, PixelYourSite o'rnatilib, faollashtiriladi."}, {"id": "q3", "prompt": "PixelYourSite plaginida Meta Pixel ID qo'yilgandan keyin qaysi katakcha yoqib qo'yiladi?", "options": [{"id": "a", "text": "Disable Pixel"}, {"id": "b", "text": "Delete all data"}, {"id": "c", "text": "Enable Advanced Matching (kengaytirilgan moslashtirish)"}, {"id": "d", "text": "Hide website"}], "correct_option_id": "c", "explanation": "Ustoz ID'dan keyin ikkinchi katakcha, ya'ni Enable Advanced Matching'ni yoqishni aytdi. Keyin Save Settings bosiladi."}, {"id": "q4", "prompt": "PixelYourSite plagini orqali pixeldan tashqari yana nima qilish mumkin?", "options": [{"id": "a", "text": "Instagram'ga post joylash"}, {"id": "b", "text": "Saytning dizaynini o'zgartirish"}, {"id": "c", "text": "Domenni tasdiqlash (Verify your domain)"}, {"id": "d", "text": "Reklamani to'lash"}], "correct_option_id": "c", "explanation": "Plaginda domen verifikatsiyasi uchun maydon bor. Facebook'dan olingan tasdiqlash kodini shu yerga qo'yib, domenni tasdiqlash mumkin."}, {"id": "q5", "prompt": "WordPress'ga pixel kodini qo'yish uchun qaysi plagin va qaysi bo'lim ishlatiladi?", "options": [{"id": "a", "text": "Yoast SEO plagini, «Keywords» bo'limi"}, {"id": "b", "text": "PixelYourSite plagini, «Domain» bo'limi"}, {"id": "c", "text": "WooCommerce plagini, «Orders» bo'limi"}, {"id": "d", "text": "Code Snippets plagini, «Header & Footer» bo'limi"}], "correct_option_id": "d", "explanation": "Code Snippets o'rnatilgach, Header & Footer bo'limidagi Header maydoniga pixel kodi qo'yiladi va Save Changes bosiladi."}, {"id": "q6", "prompt": "WordPress saytga 3-4 ta pixel o'rnatmoqchisiz. Kod orqali buni qanday qilasiz?", "options": [{"id": "a", "text": "Eski pixelni o'chirib, yangisini qo'yasiz"}, {"id": "b", "text": "Buning iloji yo'q, bitta saytga bitta pixel qo'yiladi"}, {"id": "c", "text": "Header maydoniga pixellarning kodlarini birin-ketin qo'yib chiqasiz"}, {"id": "d", "text": "Har bir pixel uchun alohida plagin o'rnatasiz"}], "correct_option_id": "c", "explanation": "Ustozning saytida header'da bitta pixel kodi turgan edi. Uning ostiga keyingi pixel kodlarini qo'shib, bir nechta pixel o'rnatsa bo'ladi."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'4-4', '4. Facebook Pixel', 4, 4, '4. Events Manager', $json$[{"id": "q1", "prompt": "Darslarda ustoz goh «hodisa», goh «event» deydi. Ularning farqi nima?", "options": [{"id": "a", "text": "Farqi yo'q, ikkalasi bir narsa: ruscha «событие», inglizcha «event», o'zbekcha «hodisa»"}, {"id": "b", "text": "Event saytda, hodisa Instagram'da bo'ladi"}, {"id": "c", "text": "Hodisa bepul, event pullik"}, {"id": "d", "text": "Event faqat xaridni, hodisa faqat lidni bildiradi"}], "correct_option_id": "a", "explanation": "Ustoz ogohlantirdi: ikkalasi bitta narsa, shuning uchun chalkashmang."}, {"id": "q2", "prompt": "Events Manager'ni qanday ochasiz?", "options": [{"id": "a", "text": "Ads Manager'da yangi kampaniya yaratib"}, {"id": "b", "text": "«Наборы данных» (Datasets) bo'limida kerakli pixelni tanlab, yuqori o'ngdagi «Открыть в Events Manager» (Open in Events Manager) tugmasini bosib"}, {"id": "c", "text": "Facebook sahifaning «Настройки» bo'limidan"}, {"id": "d", "text": "Meta Pixel Helper'ni bosib"}], "correct_option_id": "b", "explanation": "Events Manager — pixel va eventlarni boshqarish paneli. Hamma sozlamalar shu yerda qilinadi."}, {"id": "q3", "prompt": "Events Manager'dagi «Обзор» (Overview) bo'limida nima ko'rinadi?", "options": [{"id": "a", "text": "Instagram obunachilar soni"}, {"id": "b", "text": "Faqat reklama byudjeti"}, {"id": "c", "text": "Saytdagi eventlar nomi va soni, qaysi kuni, soat nechada nechta event bo'lgani"}, {"id": "d", "text": "BM'dagi adminlar ro'yxati"}], "correct_option_id": "c", "explanation": "Masalan, ustozda 11 ta PageView (saytga kirgan odamlar) va 1 ta buyurtma boshlash eventi ko'rinib turgan edi."}, {"id": "q4", "prompt": "Ustoz Tilda saytiga «Начало оформления заказа» (Initiate checkout) eventini o'zi o'rnatmagan, lekin u Events Manager'da paydo bo'ldi. Nega?", "options": [{"id": "a", "text": "Event boshqa saytdan kelgan"}, {"id": "b", "text": "Ustoz uni bilmasdan o'chirib yuborgan"}, {"id": "c", "text": "Facebook xato qilgan, bu event soxta"}, {"id": "d", "text": "Tilda'ning internet-do'kon funksiyasi pixel ulangach bu eventni avtomatik yuboradi"}], "correct_option_id": "d", "explanation": "Tilda'ga pixel o'rnatsangiz, kimdir do'kondan buyurtma berishni boshlasa, Tilda bu eventni o'zi Facebook'ga jo'natadi."}, {"id": "q5", "prompt": "«Тестовые события» (Test events) bo'limi nima uchun kerak?", "options": [{"id": "a", "text": "Saytni o'chirish uchun"}, {"id": "b", "text": "Saytga o'rnatilgan pixel va eventlar to'g'ri ishlayotganini tekshirib ko'rish uchun"}, {"id": "c", "text": "Yangi pixel yaratish uchun"}, {"id": "d", "text": "Reklamani bepul sinab ko'rish uchun"}], "correct_option_id": "b", "explanation": "Sayt manzilini yozib, «Открыть сайт» bosiladi. Saytda nima qilsangiz (sahifa ochish, tugma bosish), o'sha eventlar shu yerda darhol ko'rinadi."}, {"id": "q6", "prompt": "Test qilib bo'lgach, ustoz nimani albatta qilish kerakligini aytdi?", "options": [{"id": "a", "text": "Pixelni o'chirib, qaytadan yaratish"}, {"id": "b", "text": "Hech narsa qilmaslik, test eventlari o'zi yo'qoladi"}, {"id": "c", "text": "Test paytida tushgan eventlarni o'chirish («Удалить действия» / Clear activity), aks holda ular asosiy statistikaga qo'shilib ketadi"}, {"id": "d", "text": "Saytni boshqa domenga ko'chirish"}], "correct_option_id": "c", "explanation": "Test eventlari o'chirilmasa, «Обзор» bo'limidagi raqamlar haqiqiy holatni ko'rsatmay qoladi."}, {"id": "q7", "prompt": "«Диагностика» (Diagnostics) bo'limida nima ko'rsatiladi?", "options": [{"id": "a", "text": "Reklamaning qancha odamga ko'ringani"}, {"id": "b", "text": "Sotuvlar summasi"}, {"id": "c", "text": "Pixelni kim yaratgani"}, {"id": "d", "text": "Pixel va eventlardagi muammolar hamda ularni qanday hal qilish bo'yicha yo'riqnoma"}], "correct_option_id": "d", "explanation": "Muammo chiqsa, shu yerda ko'rinadi va yonida uni yechish uchun ko'rsatma beriladi."}, {"id": "q8", "prompt": "Events Manager «Настройки» (Settings) bo'limidagi «Владелец» (Owner) nimani bildiradi?", "options": [{"id": "a", "text": "Pixelni nechta odam ko'rganini"}, {"id": "b", "text": "Saytning hosting kompaniyasini"}, {"id": "c", "text": "Reklama akkauntining balansini"}, {"id": "d", "text": "Pixel qaysi Business Manager'ga tegishli ekanini"}], "correct_option_id": "d", "explanation": "Sozlamalarda pixel ID'si, uni kim va qachon yaratgani hamda egasi (qaysi BM) ko'rsatiladi."}, {"id": "q9", "prompt": "«Автоматическое расширенное сопоставление» (Automatic advanced matching) yoqilsa nima bo'ladi?", "options": [{"id": "a", "text": "Saytda qoldirilgan telefon va email shifrlangan holda Facebook/Instagram akkauntlari bilan solishtiriladi va eventlar haqida aniqroq ma'lumot olinadi"}, {"id": "b", "text": "Pixel o'chib qoladi"}, {"id": "c", "text": "Saytdagi mijozlarning telefon raqamlari hammaga ko'rinib qoladi"}, {"id": "d", "text": "Reklama avtomatik ravishda to'xtaydi"}], "correct_option_id": "a", "explanation": "Ma'lumotlar shifrlangan bo'ladi, ularni faqat tizim ko'radi, hech bir odam ko'rmaydi. Ustoz bu funksiyani yoqib qo'yishni aytdi."}, {"id": "q10", "prompt": "«Список разрешений / Список блокировки» (Allow list / Block list) nima uchun kerak?", "options": [{"id": "a", "text": "Instagram'da izohlarni yopish uchun"}, {"id": "b", "text": "Reklama akkauntidagi adminlarni o'chirish uchun"}, {"id": "c", "text": "Pixel ID'ingizni bilib olgan boshqa odam uni o'z saytiga qo'ysa, o'sha saytdan sizning pixelingizga event yuborilishini taqiqlash uchun"}, {"id": "d", "text": "Saytingizga kirgan har bir odamni bloklash uchun"}], "correct_option_id": "c", "explanation": "Begona sayt pixelingizga ma'lumot yuborsa, statistika buziladi. Ruxsat ro'yxati orqali faqat o'zingizning saytlaringizga ruxsat berasiz."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'4-5', '4. Facebook Pixel', 4, 5, '5. Saytga event o''rnatish', $json$[{"id": "q1", "prompt": "Saytga event o'rnatish vositasi qanday ochiladi?", "options": [{"id": "a", "text": "Meta Pixel Helper > «Delete»"}, {"id": "b", "text": "Events Manager'da «Управление интеграциями» (Manage integrations) > Pixel Meta > «Открыть инструмент настройки событий» (Open Event Setup Tool)"}, {"id": "c", "text": "Tilda > «Аналитика»"}, {"id": "d", "text": "Ads Manager > «Создать кампанию»"}], "correct_option_id": "b", "explanation": "Ikkinchi tugma pixelni yangi saytga qo'shish uchun. Bizga eventlarni sozlash kerak, shuning uchun birinchi tugma bosiladi."}, {"id": "q2", "prompt": "Event sozlash vositasini ochganda nima kiritiladi?", "options": [{"id": "a", "text": "Reklama akkaunti paroli"}, {"id": "b", "text": "Pixel o'rnatilgan saytning manzili (domeni)"}, {"id": "c", "text": "Telefon raqamingiz"}, {"id": "d", "text": "Pixel ID raqami"}], "correct_option_id": "b", "explanation": "Domen yozilib, «Открыть сайт» bosiladi. Sayt ochilib, chap yuqorida event o'rnatish paneli chiqadi."}, {"id": "q3", "prompt": "Trigger nima?", "options": [{"id": "a", "text": "Pixelning nomi"}, {"id": "b", "text": "Reklama byudjeti"}, {"id": "c", "text": "Sayt dizayni"}, {"id": "d", "text": "Facebook pixel event yuborishi uchun nima sodir bo'lishi kerakligini belgilaydigan shart"}], "correct_option_id": "d", "explanation": "Masalan: odam ma'lum sahifaga kirsa yoki ma'lum tugmani bossa, event yuborilsin. Shu «agar...» sharti trigger deyiladi."}, {"id": "q4", "prompt": "Standart eventlarda trigger qanday ikki xil bo'ladi?", "options": [{"id": "a", "text": "Reklama ishga tushganda yoki to'xtaganda"}, {"id": "b", "text": "Odam ma'lum URL (sahifa)ga kirganda yoki saytdagi ma'lum tugmani bosganda"}, {"id": "c", "text": "Instagram'ga obuna bo'lganda yoki like bosganda"}, {"id": "d", "text": "Odam saytda 1 soat o'tirganda yoki videoni ko'rganda"}], "correct_option_id": "b", "explanation": "Ustoz: vaqt, video ko'rish, sahifani aylantirish kabi murakkab triggerlar custom (maxsus) eventlarda bo'ladi, ular keyingi darslarda o'tiladi."}, {"id": "q5", "prompt": "URL trigger tanlashda «URL равен» (URL equals) va «URL содержит» (URL contains) farqi nima? Qaysi biri tavsiya qilinadi?", "options": [{"id": "a", "text": "Ikkalasi bir xil, farqi yo'q"}, {"id": "b", "text": "«Равен» — manzil harfma-harf bir xil bo'lsa ishlaydi. «Содержит» — manzilda shu qism bo'lsa ham ishlaydi. Boshqa sahifalarda yanglish ishlamasligi uchun «Равен» tavsiya qilinadi"}, {"id": "c", "text": "«Равен» faqat telefonda, «Содержит» faqat kompyuterda ishlaydi"}, {"id": "d", "text": "«Содержит» aniqroq, shuning uchun u tavsiya qilinadi"}], "correct_option_id": "b", "explanation": "«Содержит» tanlansa, manzilida shu so'z bor boshqa sahifaga kirgan odam uchun ham event yuborilib, hisob-kitob chalkashadi."}, {"id": "q6", "prompt": "Standart eventlar ro'yxatidagi «Инициирование проверки» (Initiate checkout) aslida nimani bildiradi?", "options": [{"id": "a", "text": "To'lovni boshlashni. Ruscha tarjima noto'g'ri qilingan"}, {"id": "b", "text": "Mahsulotni savatdan o'chirishni"}, {"id": "c", "text": "Saytni tekshirishni"}, {"id": "d", "text": "Pixelni test qilishni"}], "correct_option_id": "a", "explanation": "Ustoz shuni ta'kidladi: rus tilidagi tarjimada xato bor. Bu event — mijoz to'lov qilishni boshlagani."}, {"id": "q7", "prompt": "Eventdagi «Ценность» (Value), ya'ni qiymat, odatda qaysi sahifadagi eventga qo'yiladi?", "options": [{"id": "a", "text": "Saytning bosh sahifasidagi PageView'ga"}, {"id": "b", "text": "Hech qachon qo'yilmaydi"}, {"id": "c", "text": "To'lovdan keyin ochiladigan oxirgi sahifadagi xarid (Purchase) eventiga"}, {"id": "d", "text": "Har bir tugmaga"}], "correct_option_id": "c", "explanation": "Qiymat qo'yilsa, Facebook reklamalarda nechta sotuv bo'lgani va qancha pul tushgani ko'rinadi. Lid kabi eventlarda odatda «Не включать ценность» (Don't include value) tanlanadi."}, {"id": "q8", "prompt": "Ustoz asosiy sotuv sahifasiga qaysi eventni o'rnatdi va nega Lead emas?", "options": [{"id": "a", "text": "«Поиск» (Search), chunki odam sahifani qidirib topgan"}, {"id": "b", "text": "«Лид» (Lead), chunki sahifaga kirgan har bir odam lid hisoblanadi"}, {"id": "c", "text": "«Просмотр контента» (View content), chunki bu sahifaga kirgan odam hali hech qanday kontakt qoldirmagan"}, {"id": "d", "text": "«Покупка» (Purchase), chunki bu sotuv sahifasi"}], "correct_option_id": "c", "explanation": "Lead — odam ism va telefon qoldirgani. Asosiy sahifaga shunchaki kirgan odam lid emas, u kontentni ko'rgan, xolos."}, {"id": "q9", "prompt": "Sahifadagi Telegram'ga olib boradigan «Bog'lanish» tugmasiga event qanday o'rnatiladi?", "options": [{"id": "a", "text": "Pixel ID tugma matniga yoziladi"}, {"id": "b", "text": "Tugma saytdan o'chiriladi"}, {"id": "c", "text": "«Покупка» (Purchase) eventi beriladi"}, {"id": "d", "text": "«Отслеживать новую кнопку» (Track new button) bosiladi, tugma tanlanadi va «Контакт» (Contact) eventi beriladi"}], "correct_option_id": "d", "explanation": "Contact — aloqaga chiqish. Endi kimdir shu tugmani bossa, Events Manager'ga Contact eventi yuboriladi."}, {"id": "q10", "prompt": "Test paytida tugmani bosdingiz, lekin Contact eventi Events Manager'da darrov ko'rinmadi. Nima qilasiz?", "options": [{"id": "a", "text": "Bu Facebook'ning texnik nosozligi bo'lishi mumkin: biroz kutib, sahifani yangilab, qaytadan bosib tekshiraman"}, {"id": "b", "text": "Saytni boshqa domenga ko'chiraman"}, {"id": "c", "text": "Event ishlamaydi deb, undan voz kechaman"}, {"id": "d", "text": "Darhol pixelni o'chirib, yangisini yarataman"}], "correct_option_id": "a", "explanation": "Ustozda ham Contact eventi bir necha urinishdan keyin chiqdi. Ba'zan event darrov ko'rinadi, ba'zan biroz vaqt oladi."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'4-6', '4. Facebook Pixel', 4, 6, '6. Eventlar (qo''shimcha)', $json$[{"id": "q1", "prompt": "Webinar saytida 2 ta sahifa bor: reklamadan tushadigan landing va ro'yxatdan o'tgandan keyin ochiladigan sahifa. Ustoz nechta event o'rnatdi?", "options": [{"id": "a", "text": "2 ta: landingga «Просмотр контента» (View content), keyingi sahifaga «Завершение регистрации» (Complete registration)"}, {"id": "b", "text": "Hech qanday, chunki PageView yetarli"}, {"id": "c", "text": "4 ta: har bir tugmaga Lead"}, {"id": "d", "text": "1 ta: faqat landingga Purchase"}], "correct_option_id": "a", "explanation": "Har bir sahifaga alohida event qo'yilsa, har bir sahifaga qancha odam tushganini alohida ko'rasiz."}, {"id": "q2", "prompt": "Webinar saytiga 2 ta event o'rnatilsa, Events Manager'da nimani bilib olasiz?", "options": [{"id": "a", "text": "Odamlar Instagram'da nima ko'rganini"}, {"id": "b", "text": "Birinchi sahifaga necha kishi kirgani va ulardan nechtasi ro'yxatdan o'tganini"}, {"id": "c", "text": "Raqobatchilarning reklama byudjetini"}, {"id": "d", "text": "Odamlarning uy manzillarini"}], "correct_option_id": "b", "explanation": "Masalan, 100 kishi kirib, 20 tasi ro'yxatdan o'tgan bo'lsa, sahifangiz qanchalik yaxshi ishlayotganini bilasiz."}, {"id": "q3", "prompt": "Ko'p savolli anketa (so'rovnoma) to'ldirilgandan keyin ochiladigan sahifaga ustoz qaysi eventni qo'ydi?", "options": [{"id": "a", "text": "«Добавление в корзину» (Add to cart)"}, {"id": "b", "text": "«Подписка» (Subscribe)"}, {"id": "c", "text": "«Поиск» (Search)"}, {"id": "d", "text": "«Отправка заявки» (Submit application)"}], "correct_option_id": "d", "explanation": "Submit application — odam kontaktidan tashqari ko'plab savollarga javob berib, ariza yuborgani."}, {"id": "q4", "prompt": "Lead va Submit application farqi nima?", "options": [{"id": "a", "text": "Lead — odam faqat ism va telefon qoldirgan. Submit application — u anketadagi ko'p savollarga ham javob berib, to'liq ariza yuborgan"}, {"id": "b", "text": "Lead faqat Instagram'da, Submit application faqat saytda bo'ladi"}, {"id": "c", "text": "Farqi yo'q, ikkalasi bir xil"}, {"id": "d", "text": "Lead pullik, Submit application bepul"}], "correct_option_id": "a", "explanation": "Shuning uchun anketadan keyingi sahifaga Lead emas, Submit application qo'yish aniqroq bo'ladi."}, {"id": "q5", "prompt": "Odam kalendarda qo'ng'iroq uchun vaqt belgilagandan keyin ochiladigan sahifaga qaysi event qo'yiladi?", "options": [{"id": "a", "text": "«Запланировать» (Schedule)"}, {"id": "b", "text": "«Покупка» (Purchase)"}, {"id": "c", "text": "«Поиск» (Search)"}, {"id": "d", "text": "«Просмотр контента» (View content)"}], "correct_option_id": "a", "explanation": "Schedule — suhbat yoki qo'ng'iroq uchun vaqt belgilandi degani. Ruscha interfeysda «Составление расписания» deb ham yozilishi mumkin."}, {"id": "q6", "prompt": "Nega ustoz Facebook'ni rus tilida emas, ingliz tilida ishlatishni afzal ko'radi?", "options": [{"id": "a", "text": "Ingliz tilida reklama arzonroq"}, {"id": "b", "text": "Rus tilida eventlar ishlamaydi"}, {"id": "c", "text": "Ingliz tilida pixel tezroq o'rnatiladi"}, {"id": "d", "text": "Rus tilidagi tarjimalar ba'zan noto'g'ri, inglizchada esa nomlar aniq"}], "correct_option_id": "d", "explanation": "Masalan, Schedule eventining ruscha nomi ma'nosini to'liq bermaydi."}, {"id": "q7", "prompt": "Event tanlashda ustoz aytgan asosiy qoida qaysi?", "options": [{"id": "a", "text": "Eng qimmat eventni tanlash kerak"}, {"id": "b", "text": "Hamma sahifaga bir xil event qo'yish kerak"}, {"id": "c", "text": "Event nomi o'sha sahifadagi maqsadga mos kelishi kerak"}, {"id": "d", "text": "Event nomi muhim emas, istalganini qo'ysa bo'ladi"}], "correct_option_id": "c", "explanation": "Lid tushsa — Lead, savatga qo'shsa — Add to cart, aloqaga chiqsa — Contact, qidirsa — Search. Nom maqsadga to'g'ri kelishi kerak."}, {"id": "q8", "prompt": "Mijoz mahsulotni savatga qo'shib, buyurtma qoldirish sahifasiga o'tdi. Qaysi event mos keladi?", "options": [{"id": "a", "text": "«Завершение регистрации» (Complete registration)"}, {"id": "b", "text": "«Добавление в корзину» (Add to cart)"}, {"id": "c", "text": "«Запланировать» (Schedule)"}, {"id": "d", "text": "«Поиск» (Search)"}], "correct_option_id": "b", "explanation": "Mahsulot savatga qo'shildi — Add to cart. Ustoz bu holatda Lead ham bo'lishi mumkinligini aytdi."}, {"id": "q9", "prompt": "Saytdagi qidiruv (поиск) tugmasini bosgan odamlarni kuzatmoqchisiz. Qaysi event qo'yiladi?", "options": [{"id": "a", "text": "«Лид» (Lead)"}, {"id": "b", "text": "«Покупка» (Purchase)"}, {"id": "c", "text": "«Контакт» (Contact)"}, {"id": "d", "text": "«Поиск» (Search)"}], "correct_option_id": "d", "explanation": "Qidiruv tugmasi uchun Search eventi qo'yiladi. Event nomi har doim tugmaning maqsadiga mos bo'ladi."}, {"id": "q10", "prompt": "Siz xizmatingiz uchun 1 haftalik bepul sinov davrini taklif qilasiz. Shu taklifni olgan odamlarni qaysi event bilan kuzatasiz?", "options": [{"id": "a", "text": "«Просмотр контента» (View content)"}, {"id": "b", "text": "«Покупка» (Purchase)"}, {"id": "c", "text": "«Пожертвовать» (Donate)"}, {"id": "d", "text": "«Начать пробный период» (Start trial)"}], "correct_option_id": "d", "explanation": "Ustoz misol keltirdi: bir hafta bepul ishlatib ko'rish kabi takliflar uchun sinov davri eventi o'rnatiladi."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'4-7', '4. Facebook Pixel', 4, 7, '7. Purchase eventi', $json$[{"id": "q1", "prompt": "Purchase (Покупка) eventi nima uchun kerak?", "options": [{"id": "a", "text": "Reklamani avtomatik to'xtatish uchun"}, {"id": "b", "text": "Sayt yoki voronka orqali nechta sotuv bo'lgani va qancha summaga sotilganini kuzatish uchun"}, {"id": "c", "text": "Mijozlarga chek yuborish uchun"}, {"id": "d", "text": "Saytga kirganlar sonini hisoblash uchun"}], "correct_option_id": "b", "explanation": "Purchase o'rnatilsa, reklama akkauntida sotuvlar soni va ular olib kelgan daromad ko'rinadi."}, {"id": "q2", "prompt": "Ustoz misolida reklamaga taxminan 3 470$ sarflanib, 260 ta sotuv bo'ldi. Bitta sotuv taxminan necha pulga tushgan?", "options": [{"id": "a", "text": "Taxminan 26$"}, {"id": "b", "text": "Taxminan 13,35$"}, {"id": "c", "text": "Taxminan 347$"}, {"id": "d", "text": "Taxminan 1,35$"}], "correct_option_id": "b", "explanation": "3 470$ ÷ 260 ≈ 13,35$. Bu raqamni Purchase eventi o'rnatilgani uchun ko'ra olamiz."}, {"id": "q3", "prompt": "Purchase eventi o'rnatilmagan bo'lsa nima bo'ladi?", "options": [{"id": "a", "text": "Reklama umuman ishga tushmaydi"}, {"id": "b", "text": "Reklama akkauntida sotuvlar soni va summasi ko'rinmaydi"}, {"id": "c", "text": "Pixel o'chib qoladi"}, {"id": "d", "text": "Sayt ochilmay qoladi"}], "correct_option_id": "b", "explanation": "Ustoz: Purchase o'rnatmasangiz, nechta sotuv bo'lgani, qancha pul kelgani va ROAS raqamlarini ko'ra olmaysiz."}, {"id": "q4", "prompt": "Kurs sotiladigan saytda mijoz anketani to'ldirib, to'lov chekini yuklaydi va keyingi sahifaga o'tadi. Purchase eventi qaysi sahifaga o'rnatiladi?", "options": [{"id": "a", "text": "Anketa va to'lovdan keyin ochiladigan sahifaga, chunki unga faqat shu yo'l bilan tushish mumkin"}, {"id": "b", "text": "Anketa sahifasining o'ziga"}, {"id": "c", "text": "Narxlar yozilgan sahifaga"}, {"id": "d", "text": "Saytning bosh sahifasiga"}], "correct_option_id": "a", "explanation": "Facebook'ga «qachon sotuv deb hisoblash kerak» degan savolga javob beramiz: odam to'lovdan keyingi sahifaga tushganda."}, {"id": "q5", "prompt": "Purchase eventi uchun qaysi trigger tanlanadi?", "options": [{"id": "a", "text": "Instagram'da like bosganda"}, {"id": "b", "text": "Odam saytdan chiqib ketganda"}, {"id": "c", "text": "Saytda 1 soat o'tirganda"}, {"id": "d", "text": "URL orqali: «Отслеживать URL» (Track a URL), ya'ni odam o'sha sahifaga kirganda"}], "correct_option_id": "d", "explanation": "Sahifa manzili kiritiladi va event turi sifatida Purchase (Покупка) tanlanadi."}, {"id": "q6", "prompt": "Purchase eventiga sotuv narxini (qiymatini) qanday berasiz?", "options": [{"id": "a", "text": "«Выбрать ценность» (Select value) orqali narxni saytdagi sahifadan tanlab olaman, qo'lda yozilmaydi"}, {"id": "b", "text": "Narx berib bo'lmaydi"}, {"id": "c", "text": "Narxni Instagram profilga yozaman"}, {"id": "d", "text": "Narxni klaviaturada qo'lda yozaman"}], "correct_option_id": "a", "explanation": "Ikki variant bor: qiymat bermaslik yoki qiymatni sahifadan tanlash. Facebook narxni faqat sahifadagi raqamdan oladi."}, {"id": "q7", "prompt": "Ustoz mahsulot narxini sahifaga qanday yozib qo'ygan va nega?", "options": [{"id": "a", "text": "Katta qizil harflar bilan, hamma ko'rishi uchun"}, {"id": "b", "text": "Narxni rasm qilib qo'ygan"}, {"id": "c", "text": "Oq rangda, fon bilan bir xil qilib yozgan: odamlar ko'rmaydi, lekin pixel narxni shu yerdan oladi"}, {"id": "d", "text": "Narxni umuman yozmagan"}], "correct_option_id": "c", "explanation": "Narx sahifada bo'lishi kerak, aks holda pixel uni ololmaydi. Lekin mijoz «bu raqam nima?» deb chalkashmasligi uchun ko'rinmas qilib qo'yiladi."}, {"id": "q8", "prompt": "3 470$ sarflab, 75 826$ daromad olindi. Reklamaga sarflangan pul taxminan necha barobar qaytgan?", "options": [{"id": "a", "text": "Pul qaytmagan, zarar ko'rilgan"}, {"id": "b", "text": "Taxminan 100 barobar"}, {"id": "c", "text": "Taxminan 21 barobar"}, {"id": "d", "text": "Taxminan 2 barobar"}], "correct_option_id": "c", "explanation": "75 826 ÷ 3 470 ≈ 21,9. Bu ko'rsatkich ROAS deyiladi va uni faqat Purchase eventi qiymat bilan o'rnatilganda ko'rasiz."}, {"id": "q9", "prompt": "Ko'pchilik targetologlar Purchase o'rnatmaydi. Ular natijani nima orqali o'lchaydi?", "options": [{"id": "a", "text": "Hech narsa o'lchamaydi"}, {"id": "b", "text": "Sahifadagi obunachilar orqali"}, {"id": "c", "text": "Lid orqali: qancha pul sarflandi, nechta lid keldi, lidlar arzon kelyaptimi yoki qimmat"}, {"id": "d", "text": "Postlarga bosilgan like orqali"}], "correct_option_id": "c", "explanation": "Lid bilan ishlaganlar asosan lid narxi va soniga qaraydi. Purchase esa sotuv va daromadni ham ko'rsatadi."}, {"id": "q10", "prompt": "Nega Ads Manager'dagi sotuvlar summasi haqiqiy summadan biroz farq qilishi mumkin?", "options": [{"id": "a", "text": "Pixel sotuvlarni ikki marta sanaydi"}, {"id": "b", "text": "Facebook pulni o'zi yechib oladi"}, {"id": "c", "text": "Facebook to'lovdan keyingi sahifaga tushgan hammani sotuv deb hisoblaydi, lekin kimdir to'lamay, boshqa rasm yuklagan bo'lishi mumkin"}, {"id": "d", "text": "Valyuta kursi har kuni o'zgaradi"}], "correct_option_id": "c", "explanation": "Ustoz tajribasida farq katta emas, ko'pi bilan 10 foiz atrofida."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'4-8', '4. Facebook Pixel', 4, 8, '8. Pixel tugmasi ishlamayaptimi?', $json$[{"id": "q1", "prompt": "Lid qoldirilgandan keyin ochiladigan sahifada event o'rnatish imkoniyati chiqmayapti. Ustoz buning sababini nima deb tushuntirdi?", "options": [{"id": "a", "text": "Internet sekin ishlayapti"}, {"id": "b", "text": "Pixel o'chib qolgan"}, {"id": "c", "text": "Sayt boshqa domenga ko'chgan"}, {"id": "d", "text": "Sahifa juda qisqa, unda bitta-ikkita gap bor va tugma yo'q. Facebook bunday sahifani kuzatishga arzimaydi deb hisoblaydi"}], "correct_option_id": "d", "explanation": "Facebook algoritmi sahifa juda qisqa va bo'sh bo'lgani uchun uni kuzatish shart emas deb xulosa qilgan."}, {"id": "q2", "prompt": "Bu muammoni ustoz qanday hal qildi?", "options": [{"id": "a", "text": "Pixelni o'chirib, yangisini yaratdi"}, {"id": "b", "text": "Facebook'ga shikoyat yozdi"}, {"id": "c", "text": "Sahifaga tugma qo'shib, sahifani qayta nashr qildi"}, {"id": "d", "text": "Sahifani butunlay o'chirib yubordi"}], "correct_option_id": "c", "explanation": "Tugma qo'shib nashr qilgandan keyin sahifada pixel o'rnatish imkoniyati paydo bo'ldi."}, {"id": "q3", "prompt": "Nega bu qisqa sahifani baribir kuzatish kerak?", "options": [{"id": "a", "text": "Bu lid qoldirgandan keyin ochiladigan sahifa. Lidlarni hisoblash uchun aynan shu sahifani kuzatish kerak"}, {"id": "b", "text": "Bu sahifa saytning bosh sahifasi"}, {"id": "c", "text": "Bu sahifada eng ko'p reklama ko'rsatiladi"}, {"id": "d", "text": "Kuzatish shart emas, Facebook to'g'ri qilgan"}], "correct_option_id": "a", "explanation": "Lid sahifasidagi event ishlamasa, nechta lid kelganini bilmay qolasiz."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

-- ===== RASMLI TESTLAR =====
insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'4-1r', '4. Facebook Pixel', 4, 1, '1. Facebook Pixel nima — rasmli 🖼', $json$[{"id": "q1", "image": "images/4-1/q1.jpg", "keep_order": true, "prompt": "Meta Pixel Helper sahifasi ochildi. Kengaytmani brauzerga qo'shish uchun qaysi joyni bosasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: ko'k «Add to Chrome» tugmasi. «Add to Chrome» bosilib, keyin «Add extension» tasdiqlanadi. A: «View Event Log» namunasi, B: «Extensions» bo'limi, C: qidiruv maydoni."}, {"id": "q2", "image": "images/4-1/q2.jpg", "prompt": "Pixel Helper ochildi va har bir pixel ostida yashil «PageView» yozuvi turibdi. Bu nimani bildiradi?", "options": [{"id": "a", "text": "Sahifada xato bor, pixel ishlamayapti"}, {"id": "b", "text": "Sahifa ochilgani (sahifa ko'rish) eventi uchala pixelga ham muvaffaqiyatli yuborildi"}, {"id": "c", "text": "Kimdir ro'yxatdan o'tdi"}, {"id": "d", "text": "Kimdir mahsulot sotib oldi"}], "correct_option_id": "b", "explanation": "PageView pixelning standart eventi: odam sahifani ochishi bilan avtomatik ishlaydi. Yashil belgi event muvaffaqiyatli yuborilganini bildiradi."}, {"id": "q3", "image": "images/4-1/q3.jpg", "prompt": "Webinarga ro'yxatdan o'tgandan keyin shu sahifa ochildi. Pixel Helper'da PageView'dan tashqari qaysi event ko'rinyapti?", "options": [{"id": "a", "text": "Purchase — «Покупка» (xarid)"}, {"id": "b", "text": "CompleteRegistration — «Завершение регистрации» (ro'yxatdan o'tish)"}, {"id": "c", "text": "AddToCart — «Добавление в корзину»"}, {"id": "d", "text": "Lead — «Лид»"}], "correct_option_id": "b", "explanation": "Ustoz shu sahifaga Complete registration eventini o'rnatgan. Endi ro'yxatdan o'tgan odamlar alohida savatchaga yig'iladi."}, {"id": "q4", "image": "images/4-1/q4.jpg", "keep_order": true, "prompt": "Ads Manager'dagi jadval. Pastdagi harflar ustunlarni ko'rsatadi. Qaysi ustun pixel orqali kelgan ro'yxatdan o'tishlar SONINI ko'rsatadi?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: «Завершенные регистрации» (Complete registrations). Bu ustunda 250 va 32 ta ro'yxatdan o'tish ko'rinadi. Bu raqamlarni saytga pixel o'rnatilgani uchun ko'ramiz. A: «Цена за завершенную регистрацию» (Cost per registration), B: «Просмотры целевой страницы» (Landing page views), C: «CTR»."}, {"id": "q5", "image": "images/4-1/q5.jpg", "prompt": "Ustoz shu sxemani ko'rsatdi. Savatchalar nimani bildiradi?", "options": [{"id": "a", "text": "Instagram'dagi post turlarini"}, {"id": "b", "text": "Pixel saytga kelganlarni qilgan harakatiga qarab alohida guruhlarga ajratadi: sotuv sahifasiga kirganlar, anketa to'ldirganlar, video ko'rganlar, tugma bosganlar"}, {"id": "c", "text": "Reklama byudjetining taqsimlanishini"}, {"id": "d", "text": "Sayt sahifalarining dizayn variantlarini"}], "correct_option_id": "b", "explanation": "Pixel saytga o'rnatiladigan kod. U har bir harakat bo'yicha odamlarni alohida «savatchaga» yig'adi. Keyin bu savatchalardan auditoriya yaratish mumkin."}, {"id": "q6", "image": "images/4-1/q6.jpg", "keep_order": true, "prompt": "Google'da «meta pixel helper» deb qidirdingiz. Kengaytmani o'rnatish uchun qaysi natijani ochasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: chrome.google.com dagi «Meta Pixel Helper» (Chrome Web Store). Kengaytma Chrome Web Store'dan o'rnatiladi. Meta for Developers sahifasi faqat qo'llanma, u yerdan o'rnatilmaydi. A: Meta for Developers qo'llanmasi, B: «Images» bo'limi, C: Google sozlamalari."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'4-2r', '4. Facebook Pixel', 4, 2, '2. Tilda''ga pixel o''rnatish — rasmli 🖼', $json$[{"id": "q1", "image": "images/4-2/q1.jpg", "keep_order": true, "prompt": "Sahifada «Pikselning joylashuvi o'zgardi» degan yozuv bor. Yangi pixel yaratish uchun chap menyuda qaysi bo'limni bosasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "c", "explanation": "C: «Наборы данных» (Datasets). Sahifadagi yozuvda ham aytilgan: pixellar endi «Источники данных» > «Наборы данных» bo'limida. A: «Пользователи» (Users), B: «Пиксели» (Pixels), D: «Центр безопасности» (Security Center)."}, {"id": "q2", "image": "images/4-2/q2.jpg", "keep_order": true, "prompt": "Yangi pixel (набор данных) yaratish oynasi. Pixel nomini qaysi joyga yozasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "b", "explanation": "B: nom maydoni «Добавьте название…». Nomga pixel qaysi saytga o'rnatilsa, o'sha saytning nomi yoziladi. Keyin «Создать» bosiladi. A: «Справочный центр» havolasi, C: «Создать» (Create) tugmasi, D: chapdagi qidiruv maydoni."}, {"id": "q3", "image": "images/4-2/q3.jpg", "keep_order": true, "prompt": "Pixel yaratildi. Uni kod orqali saytga o'rnatish uchun shu sahifada qaysi tugmani bosasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: «Настроить пиксель Meta» (Set up Meta Pixel). «Сбор событий на сайте из активности браузера» blokidagi tugma. Conversions API murakkab darslarda o'tiladi. A: «Создать» (Create), B: «Настроить API Conversions», C: «Тестирование событий» (Test events)."}, {"id": "q4", "image": "images/4-2/q4.jpg", "keep_order": true, "prompt": "Pixel kodini qo'lda saytga qo'ymoqchisiz. Shu oynada qaysi tugmani bosasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Установить код вручную» (Install code manually). Shundan keyin pixel kodi ko'rsatiladi va uni nusxalab olasiz. B: «Отправить отзыв», C: oynani yopish (X), D: «Искать партнера» (Find a partner)."}, {"id": "q5", "image": "images/4-2/q5.jpg", "keep_order": true, "prompt": "«Установка базового кода» sahifasi. Pixel kodini nusxalash uchun qaysi tugmani bosasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Копировать код» (Copy code). Nusxalangan kod saytning head qismiga qo'yiladi (Tilda'da «HTML-код для вставки внутрь head»). B: «Отмена» (Cancel), C: chapdagi qadamlar ro'yxati, D: «Продолжить» (Continue)."}, {"id": "q6", "image": "images/4-2/q6.jpg", "keep_order": true, "prompt": "Tilda'da sayt sozlamalari ochiq. Pixel ID'ni qo'yish uchun qaysi bo'limga kirasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "b", "explanation": "B: «Аналитика» (Analytics). «Аналитика» bo'limida pastroqda «Facebook Pixel» maydoni bor, Pixel ID shu yerga qo'yiladi. A: «SEO», C: «Домен», D: «Формы»."}, {"id": "q7", "image": "images/4-2/q7.jpg", "prompt": "Pixel kodi Tilda'ning qaysi joyiga qo'yildi va saqlagandan keyin nima qilish kerak?", "options": [{"id": "a", "text": "«Домен» bo'limi. Keyin 24 soat kutish kerak"}, {"id": "b", "text": "«Вставка кода в HEAD» (head qismi). Saqlagandan keyin barcha sahifalarni qayta nashr qilish kerak"}, {"id": "c", "text": "«Аналитика» bo'limi. Keyin hech narsa qilish shart emas"}, {"id": "d", "text": "Sahifaning eng pastki bloki. Keyin sahifani o'chirish kerak"}], "correct_option_id": "b", "explanation": "Pastdagi qizil eslatmada ham yozilgan: saqlagandan keyin o'zgarish kuchga kirishi uchun barcha sahifalarni qayta nashr qiling."}, {"id": "q8", "image": "images/4-2/q8.jpg", "prompt": "Shu oyna chiqdi. U nimani bildiradi?", "options": [{"id": "a", "text": "Barcha sahifalar muvaffaqiyatli nashr qilindi. Endi o'rnatilgan pixel saytda ishlay boshlaydi"}, {"id": "b", "text": "Sayt bloklandi"}, {"id": "c", "text": "Yangi domen sotib olindi"}, {"id": "d", "text": "Pixel o'chirib yuborildi"}], "correct_option_id": "a", "explanation": "«Все страницы опубликованы успешно» — barcha sahifalar nashr qilindi. Pixel kodi saytga shundan keyin tushadi."}, {"id": "q9", "image": "images/4-2/q9.jpg", "prompt": "Ustoz o'z saytida Pixel Helper'ni ochdi. Nechta pixel topildi va nega u bir nechta pixel qo'ygan?", "options": [{"id": "a", "text": "3 ta. Bittasi bloklansa ham, auditoriya va ma'lumotlar qolgan pixellarda saqlanib qolishi uchun"}, {"id": "b", "text": "Birorta ham pixel topilmadi"}, {"id": "c", "text": "1 ta, chunki bitta saytga faqat bitta pixel qo'yiladi"}, {"id": "d", "text": "3 ta, chunki har bir pixel faqat bitta sahifani kuzatadi"}], "correct_option_id": "a", "explanation": "Yuqorida «3 pixel found» yozuvi bor. Ustoz: pixel, reklama akkaunti yoki BM bloklansa, yig'ilgan savatchalar yo'qolmasligi uchun kamida 2 ta pixel qo'ying."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'4-3r', '4. Facebook Pixel', 4, 3, '3. WordPress''ga pixel o''rnatish — rasmli 🖼', $json$[{"id": "q1", "image": "images/4-3/q1.jpg", "keep_order": true, "prompt": "WordPress'da «pixel» deb plagin qidirdingiz. Darsda Pixel ID orqali o'rnatish uchun qaysi plagin ishlatildi?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: PixelYourSite. Ustoz PixelYourSite plaginini o'rnatib, faollashtirdi va unga Pixel ID'ni qo'ydi. A: Facebook for WooCommerce, B: Meta pixel for WordPress, C: Elementor Website Builder."}, {"id": "q2", "image": "images/4-3/q2.jpg", "keep_order": true, "prompt": "PixelYourSite sozlamalari ochiq. Facebook'dan nusxalangan Pixel ID qaysi maydonga yoziladi?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: «Meta Pixel (formerly Facebook Pixel) ID». ID qo'yilgach, «Enable Advanced Matching» yoqiladi va pastdagi «Save Settings» bosiladi. A: «Click for settings» tugmasi, B: «test_event_code», C: «Conversion API» tokeni."}, {"id": "q3", "image": "images/4-3/q3.jpg", "keep_order": true, "prompt": "Pixelni kod orqali o'rnatyapsiz (Code Snippets > Header & Footer). Pixel kodi qaysi maydonga qo'yiladi?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "b", "explanation": "B: «Header». Header maydonidagi kod saytning head qismiga chiqadi (pastida «printed in the head section» deb yozilgan). Keyin «Save Changes» bosiladi. A: «Save Changes» tugmasi, C: «Testing Mode», D: «Body»."}, {"id": "q4", "image": "images/4-3/q4.jpg", "keep_order": true, "prompt": "PixelYourSite orqali domenni ham tasdiqlash mumkin. Facebook'dan olingan tasdiqlash meta-tegi qaysi maydonga qo'yiladi?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "b", "explanation": "B: «Verify your domain». Domen verifikatsiya kodi «Verify your domain» maydoniga qo'yilib, sozlamalar saqlanadi. A: «Meta Pixel ID», C: «Conversion API», D: «test_event_code»."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'4-4r', '4. Facebook Pixel', 4, 4, '4. Events Manager — rasmli 🖼', $json$[{"id": "q1", "image": "images/4-4/q1.jpg", "prompt": "Events Manager'ning «Обзор» (Overview) bo'limi. Rasmga ko'ra saytda nechta PageView eventi qayd etilgan?", "options": [{"id": "a", "text": "28 ta"}, {"id": "b", "text": "11 ta"}, {"id": "c", "text": "5 ta"}, {"id": "d", "text": "1 ta"}], "correct_option_id": "b", "explanation": "Pastdagi jadvalda PageView qarshisida, «Общее число событий» ustunida 11 yozilgan. «Начало оформления заказа» esa 1 ta."}, {"id": "q2", "image": "images/4-4/q2.jpg", "keep_order": true, "prompt": "Saytga o'rnatilgan pixel va eventlar ishlayotganini tekshirish uchun qaysi bo'limga kirasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: «Тестирование событий» (Test events). Bu yerda sayt manzili yozilib, sayt ochiladi va u yerda qilingan har bir harakat event bo'lib darhol ko'rinadi. A: «История» (History), B: «Настройки» (Settings), C: «Диагностика» (Diagnostics)."}, {"id": "q3", "image": "images/4-4/q3.jpg", "prompt": "Test paytida ustoz saytdagi qizil buyurtma tugmasini bosdi. Rasmga ko'ra bu qaysi event bo'lib tushdi?", "options": [{"id": "a", "text": "«Контакт» (Contact)"}, {"id": "b", "text": "«Покупка» (Purchase)"}, {"id": "c", "text": "SubscribedButtonClick — «Автоматический вход», ya'ni avtomatik aniqlangan tugma bosish"}, {"id": "d", "text": "«Лид» (Lead)"}], "correct_option_id": "c", "explanation": "Ustoz bu eventni o'zi o'rnatmagan. Tilda bilan integratsiya bo'lgani uchun tugma bosilishi avtomatik yuborildi."}, {"id": "q4", "image": "images/4-4/q4.jpg", "keep_order": true, "prompt": "Test tugadi va shu oyna chiqdi. Test eventlarini statistikadan olib tashlash uchun qaysi tugmani bosasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "b", "explanation": "B: «Удалить действия» (Clear activity). Test eventlari o'chirilmasa, «Обзор» bo'limidagi raqamlarga qo'shilib, statistikani chalkashtiradi. A: «Выбранные варианты», C: oynani yopish (X), D: «Отмена» (Cancel)."}, {"id": "q5", "image": "images/4-4/q5.jpg", "prompt": "«Настройки» (Settings) bo'limidagi bu kalitlar («Электронный адрес», «Номер телефона», «Имя и фамилия»…) qaysi funksiyaga tegishli?", "options": [{"id": "a", "text": "«Диагностика» (Diagnostics)"}, {"id": "b", "text": "«Автоматическое расширенное сопоставление» (Automatic advanced matching)"}, {"id": "c", "text": "«Список блокировки» (Block list)"}, {"id": "d", "text": "«Тестирование событий» (Test events)"}], "correct_option_id": "b", "explanation": "Saytda qoldirilgan email, telefon va boshqa ma'lumotlar shifrlangan holda Facebook/Instagram akkauntlari bilan solishtiriladi. Hech kim ularni ko'rmaydi, eventlar aniqroq bo'ladi."}, {"id": "q6", "image": "images/4-4/q6.jpg", "prompt": "«Управляйте разрешениями для трафика» oynasi nima uchun kerak?", "options": [{"id": "a", "text": "Reklama akkauntidagi adminlarni o'chirish uchun"}, {"id": "b", "text": "Instagram'da izohlarni yopish uchun"}, {"id": "c", "text": "Faqat ruxsat ro'yxatidagi domenlardan event qabul qilish uchun: Pixel ID'ingizni bilgan begona sayt pixelingizga ma'lumot yubora olmaydi"}, {"id": "d", "text": "Saytingizga kirgan hamma odamni bloklash uchun"}], "correct_option_id": "c", "explanation": "Begona sayt pixelingizga event yuborsa, statistika buziladi. Shuning uchun o'z domeningizni ruxsat ro'yxatiga qo'shasiz."}, {"id": "q7", "image": "images/4-4/q7.jpg", "keep_order": true, "prompt": "Pixel sozlamalari. Pixel qaysi Business Manager'ga tegishli ekanini qaysi joydan bilasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "c", "explanation": "C: «Владелец» (Owner). «Владелец» — pixel egasi, ya'ni qaysi BMga tegishli. «Автор» — pixelni kim va qachon yaratgani. A: «ID группы данных» (Dataset ID), B: «Автор» (Author), D: «Связать» (Link)."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'4-5r', '4. Facebook Pixel', 4, 5, '5. Saytga event o''rnatish — rasmli 🖼', $json$[{"id": "q1", "image": "images/4-5/q1.jpg", "keep_order": true, "prompt": "Events Manager «Обзор» sahifasi. Event sozlash vositasiga o'tish uchun qaysi havolani bosasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Управление интеграциями» (Manage integrations). Keyin Pixel Meta integratsiyasi tanlanib, «Открыть инструмент настройки событий» bosiladi. B: «Тестирование событий» (Test events), C: «Настройки» (Settings), D: «Создать» (Create)."}, {"id": "q2", "image": "images/4-5/q2.jpg", "keep_order": true, "prompt": "Shu oyna ochildi. Kod yozmasdan event qo'shish uchun qaysi tugmani bosasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "b", "explanation": "B: «Открыть инструмент настройки событий» (Open Event Setup Tool). Bu eng oson yo'l: kod yozmasdan, saytning o'zida bosib event qo'shiladi. A: «Подробнее», C: «Установите события с помощью кода», D: «Отправить отзыв»."}, {"id": "q3", "image": "images/4-5/q3.jpg", "keep_order": true, "prompt": "Sayt ochildi, chapda event sozlash paneli chiqdi. Asosiy sahifaga kirganlar uchun URL bo'yicha event qo'shmoqchisiz. Qaysi tugmani bosasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Отслеживать URL» (Track a URL). Sahifaga kirganda event yuborish uchun URL trigger tanlanadi. Tugma bosilganda yuborish uchun esa «Отслеживать новую кнопку». B: «Отслеживать новую кнопку» (Track new button), C: «Все события» (All events), D: «Завершить настройку» (Finish setup)."}, {"id": "q4", "image": "images/4-5/q4.jpg", "prompt": "URL bo'yicha event qo'shish oynasida «URL соответствует» (URL equals) tanlangan. Bu nimani bildiradi?", "options": [{"id": "a", "text": "Event faqat tugma bosilganda yuboriladi"}, {"id": "b", "text": "Event faqat sahifa manzili yozilgan URL bilan harfma-harf bir xil bo'lganda yuboriladi"}, {"id": "c", "text": "Manzilda shu so'z qatnashsa ham event yuboriladi"}, {"id": "d", "text": "Saytning hamma sahifalarida event ishlaydi"}], "correct_option_id": "b", "explanation": "Boshqa sahifalarda yanglish ishlamasligi uchun «URL соответствует» tavsiya qilinadi. «URL содержит» (contains) esa manzilda shu qism bo'lsa ham ishlaydi."}, {"id": "q5", "image": "images/4-5/q5.jpg", "prompt": "Bu oynada «Лид» (Lead) eventi tanlangan. «Значение» (qiymat) bo'limida ustoz qaysi variantni tanladi va nega?", "options": [{"id": "a", "text": "Valyutani USD'dan so'mga o'zgartirdi"}, {"id": "b", "text": "Qiymat bo'limini butunlay o'chirib yubordi"}, {"id": "c", "text": "«Не включать значение» (Don't include value): lidda narx yo'q, qiymat odatda to'lovdan keyingi xarid sahifasiga qo'yiladi"}, {"id": "d", "text": "«Выбрать значение на странице»: har bir lidga 1 250 000 so'm yoziladi"}], "correct_option_id": "c", "explanation": "Ustoz: odatda qiymat faqat to'lov qilingandan keyin ochiladigan oxirgi sahifadagi Purchase eventiga beriladi."}, {"id": "q6", "image": "images/4-5/q6.jpg", "prompt": "Eventlar ro'yxatidagi «Инициация проверки» (Initiate checkout) aslida nimani bildiradi?", "options": [{"id": "a", "text": "Saytni tekshirishni"}, {"id": "b", "text": "Pixelni test qilishni"}, {"id": "c", "text": "To'lovni boshlashni. Ruscha tarjima noto'g'ri qilingan"}, {"id": "d", "text": "Mahsulotni savatdan o'chirishni"}], "correct_option_id": "c", "explanation": "Ustoz ogohlantirdi: ruscha nomda xato bor, bu event mijoz to'lov qilishni boshlaganini bildiradi."}, {"id": "q7", "image": "images/4-5/q7.jpg", "keep_order": true, "prompt": "Telegram tugmasiga «Контакт» eventi qo'shildi. Sozlashni yakunlash uchun qaysi tugmani bosasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Готово» (Done). «Завершить настройку» oynasida qo'shilgan eventlar ko'rinadi. «Готово» bosilsa, sozlash saqlanadi. B: oynani yopish (X), C: «Удалить» (Delete), D: «Назад» (Back)."}, {"id": "q8", "image": "images/4-5/q8.jpg", "keep_order": true, "prompt": "Test qilinmoqda. Qaysi qator ustoz Event Setup Tool orqali o'zi o'rnatgan eventni ko'rsatadi?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "c", "explanation": "C: «Просмотр контента» (View content). «Способ настройки» ustunida «Инструмент настройки событий» deb yozilgan. SubscribedButtonClick avtomatik, PageView esa kod orqali keladi. A: PageView, B: «Удалить действие» tugmasi, D: SubscribedButtonClick."}, {"id": "q9", "image": "images/4-5/q9.jpg", "keep_order": true, "prompt": "Panelda «Просмотр контента» qo'shilgan. Endi sahifadagi «Bog'lanish» tugmasini bosganlarni kuzatmoqchisiz. Qaysi tugmani bosasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Отслеживать новую кнопку» (Track new button). Keyin sahifadagi kerakli tugma tanlanadi va unga «Контакт» (Contact) eventi beriladi. B: «Завершить настройку» (Finish setup), C: «Отслеживать URL» (Track a URL), D: event'ni tahrirlash belgisi."}, {"id": "q10", "image": "images/4-5/q10.jpg", "prompt": "Ko'k «Get your lesson» tugmasiga qaysi event biriktirilgan?", "options": [{"id": "a", "text": "«Покупка» (Purchase)"}, {"id": "b", "text": "«Лид» (Lead)"}, {"id": "c", "text": "«Просмотр контента» (View content)"}, {"id": "d", "text": "«Контакт» (Contact): tugma bosilganda aloqaga chiqish eventi yuboriladi"}], "correct_option_id": "d", "explanation": "Paneldagi yozuvga qarang: «Контакт — Button text is: get your lesson». Tugma yonidagi yashil belgi u kuzatilayotganini bildiradi."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'4-6r', '4. Facebook Pixel', 4, 6, '6. Eventlar (qo''shimcha) — rasmli 🖼', $json$[{"id": "q1", "image": "images/4-6/q1.jpg", "prompt": "Bu sahifa ko'p savolli anketa to'ldirilgandan keyin ochiladi. Unga qaysi event qo'yiladi?", "options": [{"id": "a", "text": "«Покупка» (Purchase)"}, {"id": "b", "text": "«Поиск» (Search)"}, {"id": "c", "text": "«Отправка заявки» (Submit application)"}, {"id": "d", "text": "«Добавление в корзину» (Add to cart)"}], "correct_option_id": "c", "explanation": "Odam ko'p savolga javob berib, to'liq ariza yubordi. Shuning uchun bu yerda Lead emas, Submit application aniqroq."}, {"id": "q2", "image": "images/4-6/q2.jpg", "prompt": "Bu sahifada mijoz nima qiladi?", "options": [{"id": "a", "text": "Webinarga ro'yxatdan o'tadi"}, {"id": "b", "text": "Mahsulot uchun to'lov qiladi"}, {"id": "c", "text": "Saytdan mahsulot qidiradi"}, {"id": "d", "text": "Mutaxassis qo'ng'iroq qilishi uchun kun va bo'sh vaqtni tanlaydi"}], "correct_option_id": "d", "explanation": "Kalendardan kun va soat tanlanadi. Vaqt belgilangach, keyingi sahifa ochiladi va unga Schedule eventi qo'yiladi."}, {"id": "q3", "image": "images/4-6/q3.jpg", "prompt": "Qo'ng'iroq vaqti belgilangandan keyin shu sahifa ochiladi. Unga qaysi event qo'yiladi?", "options": [{"id": "a", "text": "«Лид» (Lead)"}, {"id": "b", "text": "«Просмотр контента» (View content)"}, {"id": "c", "text": "«Составление расписания» (Schedule)"}, {"id": "d", "text": "«Подписка» (Subscribe)"}], "correct_option_id": "c", "explanation": "Schedule — suhbat yoki qo'ng'iroq uchun vaqt belgilandi degani. Ustoz aytganidek, ruscha nom ma'noni to'liq bermaydi, inglizchada aniqroq."}, {"id": "q4", "image": "images/4-6/q4.jpg", "keep_order": true, "prompt": "Siz 1 haftalik bepul sinov taklif qilasiz. Shu taklifni olganlarni kuzatish uchun ro'yxatdan qaysi eventni tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Начало пробного периода» (Start trial). Event nomi sahifadagi maqsadga mos bo'lishi kerak: bepul sinov — Start trial. B: «Подписка» (Subscribe), C: «Отправка заявки» (Submit application), D: «Поиск» (Search)."}, {"id": "q5", "image": "images/4-6/q5.jpg", "prompt": "Rasmga ko'ra nechta odam «Контакт» (Contact) eventini bajargan, ya'ni aloqaga chiqish tugmasini bosgan?", "options": [{"id": "a", "text": "3 ta"}, {"id": "b", "text": "1 ta"}, {"id": "c", "text": "50 ta"}, {"id": "d", "text": "21 ta"}], "correct_option_id": "a", "explanation": "Jadvalda «Контакт» qarshisida 3 yozilgan. 50 — PageView, 21 — «Просмотр контента», 1 — «Лид»."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'4-7r', '4. Facebook Pixel', 4, 7, '7. Purchase eventi — rasmli 🖼', $json$[{"id": "q1", "image": "images/4-7/q1.jpg", "keep_order": true, "prompt": "Ads Manager'dagi jadval. Pastdagi harflar ustunlarni ko'rsatadi. Qaysi ustun Purchase orqali kelgan daromad summasini ko'rsatadi?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: «Ценность конверсии покупок» (Purchase conversion value). Bu ustunda jami 75 826 $ ko'rinadi. Bu raqam Purchase eventi qiymat bilan o'rnatilgani uchun chiqadi. A: «Сумма затрат» (Amount spent), B: «Цена за покупку» (Cost per purchase), C: «Покупки» (Purchases)."}, {"id": "q2", "image": "images/4-7/q2.jpg", "keep_order": true, "prompt": "Events Manager'dagi eventlar ro'yxati. Sotuvlarni sanaydigan Purchase eventi qaysi?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "b", "explanation": "B: «Покупка» (Purchase). Purchase ruscha interfeysda «Покупка» deb ataladi. A: «Лид» (Lead), C: «Просмотр контента» (View content), D: «Завершенная регистрация» (Complete registration)."}, {"id": "q3", "image": "images/4-7/q3.jpg", "prompt": "Purchase eventini o'rnatish uchun shu oyna ochildi. «URL сайта» maydoniga nima yoziladi?", "options": [{"id": "a", "text": "Event o'rnatiladigan saytning manzili, keyin «Открыть сайт» bosiladi"}, {"id": "b", "text": "Pixel ID raqami"}, {"id": "c", "text": "Reklama akkauntining nomi"}, {"id": "d", "text": "Mahsulot narxi"}], "correct_option_id": "a", "explanation": "Sayt ochilgach, to'lovdan keyingi sahifaga o'tib, u yerga URL bo'yicha Purchase eventi qo'yiladi."}, {"id": "q4", "image": "images/4-7/q4.jpg", "keep_order": true, "prompt": "Mijoz kartaga pul o'tkazadi, anketani to'ldirib, chek rasmini yuklaydi. Qaysi tugma bosilgandan keyin ochiladigan sahifaga Purchase eventi qo'yiladi?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "c", "explanation": "C: «Ro'yxatdan o'tish» tugmasi. Anketa yuborilgandan keyin ochiladigan sahifaga faqat to'lov qilib, anketa to'ldirgan odam tusha oladi. Shuning uchun Purchase o'sha sahifaga qo'yiladi. A: «Choose File» (chek yuklash), B: «Menejer bilan bog'lanish», D: «Ismingiz» maydoni."}, {"id": "q5", "image": "images/4-7/q5.jpg", "keep_order": true, "prompt": "Purchase eventiga sotuv narxini berish kerak. Narxni sahifadan olish uchun qaysi variantni tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Выбрать значение на странице» (Select value on page). Narx qo'lda yozilmaydi: «Выбрать значение на странице» tanlanib, sahifadagi narx bosiladi. B: «Не включать значение» (Don't include value), C: «Использовать значение из события…», D: «Валюта» (Currency)."}, {"id": "q6", "image": "images/4-7/q6.jpg", "prompt": "Narx sahifadan tanlandi. Rasmga ko'ra Facebook qanday qiymat oldi va bu narx sahifada qanday turibdi?", "options": [{"id": "a", "text": "0. Qiymat olinmadi"}, {"id": "b", "text": "800. Narx sahifada oq rangda, fon bilan bir xil qilib yozilgan, mijozga ko'rinmaydi"}, {"id": "c", "text": "1 250 000. Sahifadagi katta qizil narx"}, {"id": "d", "text": "800. Ustoz uni klaviaturada qo'lda yozdi"}], "correct_option_id": "b", "explanation": "O'ngdagi «Значение 800» belgisi tanlangan joyni ko'rsatadi. Narx sahifada bo'lishi shart, lekin mijoz chalkashmasligi uchun oq rangda yashirilgan."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'4-8r', '4. Facebook Pixel', 4, 8, '8. Pixel tugmasi ishlamayaptimi? — rasmli 🖼', $json$[{"id": "q1", "image": "images/4-8/q1.jpg", "prompt": "Lid sahifasida event sozlash paneli ochildi, lekin «Отслеживать новую кнопку» va «Отслеживать URL» tugmalari xira, bosilmayapti. Sababi nima?", "options": [{"id": "a", "text": "Sahifa juda qisqa va unda tugma yo'q, Facebook uni kuzatishga arzimaydi deb hisoblagan"}, {"id": "b", "text": "Pixel o'chib qolgan"}, {"id": "c", "text": "Sayt boshqa domenga ko'chirilgan"}, {"id": "d", "text": "Internet sekin ishlayapti"}], "correct_option_id": "a", "explanation": "Sahifada bitta-ikkita gap bor, xolos. Facebook algoritmi bunday sahifani kuzatish shart emas deb xulosa qilgan."}, {"id": "q2", "image": "images/4-8/q2.jpg", "keep_order": true, "prompt": "Ustoz Tilda'da sahifaga tugmalar blokini qo'shdi. O'zgarish saytda ko'rinishi uchun qaysi tugmani bosasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Опубликовать» (Publish). Tugma qo'shilib, sahifa qayta nashr qilingach, event sozlash panelidagi tugmalar ishlay boshladi. B: «Предпросмотр» (Preview), C: «Настройки» (Settings), D: «Отменить» (Cancel)."}, {"id": "q3", "image": "images/4-8/q3.jpg", "prompt": "Tugma qo'shilib, sahifa nashr qilingach, panel ishladi. Rasmga ko'ra shu sahifaga qaysi event qo'shildi?", "options": [{"id": "a", "text": "«Контакт» (Contact), tugma bo'yicha"}, {"id": "b", "text": "«Покупка» (Purchase)"}, {"id": "c", "text": "«Просмотр контента» (View content)"}, {"id": "d", "text": "«Лид» (Lead), URL bo'yicha (URL equals)"}], "correct_option_id": "d", "explanation": "Bu lid qoldirilgandan keyin ochiladigan sahifa. Shu sahifaga tushgan har bir odam lid sifatida sanaladi."}]$json$::jsonb, true)
